// One run at a time. The lock expires after 90 minutes so a crashed run cannot block the next ones.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
if (sd.lockUntil && sd.lockUntil > now) return [{ json: { locked: true, until: new Date(sd.lockUntil).toISOString() } }];
sd.lockUntil = now + 90 * 60 * 1000;
return [{ json: { locked: false } }];

const cfg = $('Config').first().json;
// ALL = every tab that has an Etsy category set up (2026Instock has none, so it is left out)
const ALL = ['Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const raw = String(cfg.tabs || '').trim();
const tabs = raw.toUpperCase() === 'ALL' ? ALL : raw.split(',').map(s => s.trim()).filter(Boolean);
return tabs.map(t => ({ json: { tab: t, url: 'https://sheets.googleapis.com/v4/spreadsheets/' + cfg.docId + '/values/' + encodeURIComponent("'" + t.replace(/'/g, "''") + "'!2:1500") + '?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE' } }));

// Chooses up to perTab rows for each tab. The create workflow checks every row again before it sends anything to Etsy.
const cfg = $('Config').first().json;
const tabItems = $('Tabs').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const nk = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const yes = v => /^(yes|true|1)$/i.test(String(v || '').trim());
const cap = Number(cfg.perTab) || 3;
const out = [], skipped = [];
tabItems.forEach((t, k) => {
  const res = results[k] || {};
  if (res.error || !res.values) { skipped.push({ tab: t.tab, reason: 'could not read the tab' }); return; }
  const rows = res.values;
  const hk = (rows[0] || []).map(nk);
  const ix = n => hk.indexOf(nk(n));
  const skuCol = hk.lastIndexOf('productno');
  const c = { title: ix('Title_Etsy'), desc: ix('Description_Etsy'), tags: ix('Tags_Etsy'), price: ix('Price In CAD'), img1: ix('IMAGE URL1'), img2: ix('IMAGE URL2'), ready: ix('Etsy_ready_to_post'), listing: ix('Etsy_listing_id'), status: ix('Etsy_status') };
  if (skuCol < 0 || Object.values(c).some(v => v < 0)) { skipped.push({ tab: t.tab, reason: 'missing column(s)' }); return; }
  const cell = (r, i) => (r[i] == null ? '' : String(r[i]).trim());
  const count = {};
  for (let i = 1; i < rows.length; i++) { const s = cell(rows[i] || [], skuCol).toUpperCase(); if (s) count[s] = (count[s] || 0) + 1; }
  const validTags = s => { const seen = new Set(); s.split(/[,;\n|]+/).forEach(x => { x = x.replace(/[^\p{L}\p{N} \-']/gu, '').replace(/\s+/g, ' ').trim(); if (x && x.length <= 20) seen.add(x.toLowerCase()); }); return seen.size; };
  let n = 0;
  for (let i = 1; i < rows.length && n < cap; i++) {
    const r = rows[i] || [];
    const sku = cell(r, skuCol);
    if (!sku || count[sku.toUpperCase()] > 1) continue;
    if (!yes(cell(r, c.ready)) || cell(r, c.listing) || cell(r, c.status)) continue;
    if (!cell(r, c.title) || !cell(r, c.desc) || !(parseFloat(cell(r, c.price)) > 0)) continue;
    if (!/^https?:/i.test(cell(r, c.img1)) && !/^https?:/i.test(cell(r, c.img2))) continue;
    if (cfg.requireFullTags !== false && validTags(cell(r, c.tags)) < 13) continue;
    out.push({ json: { tab: t.tab, sku, apiKey: cfg.apiKey, shopId: cfg.shopId, docId: cfg.docId, shippingProfileId: cfg.shippingProfileId, readinessStateId: cfg.readinessStateId, dryRun: cfg.dryRun !== false, requireFullTags: cfg.requireFullTags !== false } });
    n++;
  }
});
if (!out.length) return [{ json: { noRows: true, skipped } }];
return out;

const sd = $getWorkflowStaticData('global'); sd.lockUntil = 0;
const j = $input.first().json;
return [{ json: { done: true, message: 'No rows to create (flagged, 13 tags, no listing yet).', skipped: j.skipped || [] } }];

const items = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global'); sd.lockUntil = 0;
const rows = items.map(j => ({ tab: j.tab, sku: j.sku, row: j.row, status: j.status || (j.ok === false ? 'not_ready' : (j.dryRun ? 'dry_run_ok' : 'unknown')), listingId: j.listingId || null, adminUrl: j.adminUrl || null, images: j.imagesOnEtsy != null ? j.imagesOnEtsy + ' of ' + j.imagesExpected : undefined, problems: j.errors && j.errors.length ? j.errors : (j.problems && j.problems.length ? j.problems : []), notes: j.notes || [] }));
const by = {}; rows.forEach(r => { by[r.status] = (by[r.status] || 0) + 1; });
return [{ json: { dryRun: $('Config').first().json.dryRun !== false, processed: rows.length, byStatus: by, rows } }];
